"use client";
import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import "./folder-fan.css";
import { createFolderLidMotion, folderItemMotion } from "./folder-motion";
import { createPositionMotion, type PositionMotion } from "./franklin-react-motion-position";
import { boundsOf, folderFanLayout, folderPocket } from "./franklin-react-core-containers";
import type { BoardItem } from "./franklin-react-core-types";
import { useControllableState } from "./use-controllable-state";
export interface FolderItem {
  id: string;
  label: string;
  content?: ReactNode;
  color?: string;
}
export interface FolderFanProps {
  className?: string;
  style?: CSSProperties;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  items: FolderItem[];
  title?: string;
  onSelect?: (id: string) => void;
  /** @deprecated The shared Board layout determines card spacing. */
  spread?: number;
  direction?: "up" | "right";
  material?: "paper" | "glass";
  color?: string;
  /** @deprecated Motion now uses the shared Franklin spring profiles. */
  duration?: number;
  trigger?: "press" | "hover";
}
/** One retained card tree, using the same layout and springs as BoardFolder.
 * Hover is optional; the toggle remains operable by touch and keyboard.
 */
export function FolderFan({
  items,
  className = "",
  style,
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  title = "Collection",
  onSelect,
  spread: _spread,
  direction = "up",
  material = "glass",
  color = "var(--roc-secondary, #2563eb)",
  duration: _duration,
  trigger = "press",
}: FolderFanProps) {
  const [pinned, setPinned] = useControllableState(
    controlled,
    defaultOpen,
    onOpenChange,
  );
  const [hovered, setHovered] = useState(false);
  const root = useRef<HTMLDivElement>(null),
    id = useId();
  const open = pinned || (trigger === "hover" && hovered);
  const side = direction === "right";
  const nodes = useRef(new Map<string, HTMLButtonElement>());
  const world = useRef<HTMLDivElement>(null), lid = useRef<HTMLButtonElement>(null);
  const latest = useRef({ items, open, side }); latest.current = { items, open, side };
  const sync = useRef<(() => void) | null>(null);
  useLayoutEffect(() => {
    const host = root.current!, scene = world.current!, cover = lid.current!;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)");
    const motions = new Map<string, PositionMotion>();
    const destinations = new Map<string, string>();
    let lidMotion = createFolderLidMotion(cover, latest.current.open ? 20 : 0, latest.current.side);
    const camera = createPositionMotion(scene, { x: 0, y: 0, scale: 1 }, pose => {
      scene.style.transform = `translate(${pose.x}px, ${pose.y}px) scale(${pose.scale})`;
    });
    let mounted = false, previousOpen = latest.current.open, previousSide = latest.current.side;
    sync.current = () => {
      const state = latest.current;
      const folder: BoardItem = { id: "folder", type: "folder", x: 0, y: 0, width: 228, height: 176, data: {} };
      const cards: BoardItem[] = state.items.map(item => ({ id: item.id, type: "card", x: 0, y: 0, width: 118, height: 152, data: {} }));
      const fan = folderFanLayout(folder, cards);
      const poses = cards.map((item, index) => {
        const pose = state.open ? fan.get(item.id)! : folderPocket(item, folder, index);
        // Side-opening folders rotate the same local arrangement around the pocket.
        if (state.side && state.open) return { ...pose, x: folder.width + 24 + Math.max(0, -pose.y - item.height), y: pose.x + item.width / 2 - item.height / 2 };
        return pose;
      });
      const bounds = boundsOf([folder, ...cards.map((item,index) => ({ ...item, ...poses[index] }))])!;
      const scale = Math.min(1, Math.max(1, host.clientWidth - 48) / bounds.width, Math.max(1, host.clientHeight - 48) / bounds.height);
      const target = { x: host.clientWidth / 2 - (bounds.x + bounds.width / 2) * scale, y: host.clientHeight / 2 - (bounds.y + bounds.height / 2) * scale, scale };
      if (mounted && previousOpen !== state.open) camera.to(target, reduced.matches); else camera.set(target);
      const ids = new Set(cards.map(item => item.id));
      for (const [key, motion] of motions) if (!ids.has(key)) { motion.dispose(); motions.delete(key); destinations.delete(key); }
      cards.forEach((item,index) => {
        const node = nodes.current.get(item.id); if (!node) return;
        let motion = motions.get(item.id);
        const destination = JSON.stringify(poses[index]);
        if (!motion) { motion = createPositionMotion(node, poses[index]); motions.set(item.id, motion); }
        else if (destinations.get(item.id) !== destination) motion.to(poses[index], reduced.matches, folderItemMotion(state.open));
        destinations.set(item.id, destination);
      });
      if (previousSide !== state.side) { lidMotion.dispose(); lidMotion = createFolderLidMotion(cover, state.open ? 20 : 0, state.side); }
      lidMotion.to(state.open ? 20 : 0, reduced.matches);
      previousOpen = state.open; previousSide = state.side; mounted = true;
    };
    sync.current();
    const resize = new ResizeObserver(() => sync.current?.()); resize.observe(host);
    const preference = () => { if (reduced.matches) { motions.forEach(motion => motion.finish()); camera.finish(); lidMotion.finish(); } };
    reduced.addEventListener("change", preference);
    return () => { resize.disconnect(); reduced.removeEventListener("change", preference); motions.forEach(motion => motion.dispose()); camera.dispose(); lidMotion.dispose(); sync.current = null; };
  }, []);
  useLayoutEffect(() => { sync.current?.(); });
  return (
    <div
      ref={root}
      data-direction={direction}
      data-material={material}
      className={`roc-folder ${open ? "is-open" : ""} ${className}`}
      style={
        {
          "--folder-color": color,
          ...style,
        } as CSSProperties
      }
      onPointerEnter={(e) => {
        if (e.pointerType === "mouse") setHovered(true);
      }}
      onPointerLeave={() => setHovered(false)}
      onKeyDown={(e) => {
        if (e.key === "Escape" && open) {
          e.stopPropagation();
          setPinned(false);
          setHovered(false);
          root.current
            ?.querySelector<HTMLButtonElement>(".roc-folder-toggle")
            ?.focus();
        }
      }}
    >
      <div className="roc-folder-world" ref={world}>
      <div className="roc-folder-back" aria-hidden="true" />
      <div
        id={id}
        className="roc-folder-items"
        inert={!open}
        aria-hidden={!open}
      >
        {items.map((item, index) => {
          return (
            <button
              type="button"
              key={item.id}
              ref={node => { if (node) nodes.current.set(item.id, node); else nodes.current.delete(item.id); }}
              data-roc-item
              className="roc-folder-card"
              onClick={() => onSelect?.(item.id)}
              style={{
                background: item.color,
                zIndex: index + 1,
              }}
            >
              <span className="roc-eyebrow">
                {String(index + 1).padStart(2, "0")}
              </span>
              <strong>{item.label}</strong>
              <span className="roc-card-content">{item.content}</span>
            </button>
          );
        })}
      </div>
      <button
        type="button"
        ref={lid}
        className="roc-folder-toggle"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => {
          setPinned(!open);
          setHovered(false);
        }}
      >
        <span>{title}</span>
        <span>
          {items.length} objects <b>{open ? "−" : "+"}</b>
        </span>
      </button>
      </div>
    </div>
  );
}

@import "./surface.css";
.roc-folder {
  height: 340px;
  width: 100%;
  max-width: 500px;
  position: relative;
  isolation: isolate;
  margin: auto;
  container-type: inline-size;
}
.roc-folder-back {
  position: absolute;
  left: 50%;
  top: 49%;
  width: 210px;
  height: 150px;
  transform: translateX(-50%);
  border-radius: 8px 18px 15px 15px;
  background: color-mix(in srgb, var(--folder-color, #a8c6ee), #454d5c 13%);
  border: 1px solid #ffffff50;
  box-shadow: inset 0 1px #ffffff70;
  transition: left var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1);
}
.roc-folder-back:before {
  content: "";
  position: absolute;
  width: 80px;
  top: -14px;
  height: 25px;
  background: inherit;
  border-radius: 9px 14px 0 0;
}
.roc-folder-items {
  position: absolute;
  inset: 0;
  z-index: 1;
}
.roc-folder-card {
  position: absolute;
  width: 118px;
  height: 152px;
  padding: 12px;
  text-align: left;
  border: 1px solid #ffffff70;
  border-radius: var(--roc-radius, 9px);
  background: var(--roc-paper, #fffcf6);
  box-shadow: 0 5px 14px #22222216;
  transform-origin: center;
  transition:
    left var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    top var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    transform var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    box-shadow 0.2s;
}
.roc-folder-card:hover {
  box-shadow: 0 13px 24px #22222220;
}
.roc-folder-card strong {
  display: block;
  font:
    normal 20px/1.15 var(--roc-font-heading, system-ui);
  margin-top: 18px;
  overflow-wrap: anywhere;
}
.roc-card-content {
  display: block;
  margin-top: 12px;
  font-size: 10px;
  line-height: 1.5;
  color: var(--roc-muted, #757b72);
}
.roc-folder-toggle {
  position: absolute;
  z-index: 2;
  left: 50%;
  top: 58%;
  width: 228px;
  height: 133px;
  padding: 22px;
  border: 1px solid #ffffff90;
  border-radius: 9px 9px 19px 19px;
  text-align: left;
  transform: translateX(-50%);
  transform-origin: 50% 100%;
  background: var(--folder-color, #a8c6ee);
  box-shadow:
    inset 0 1px 1px #ffffff70,
    0 14px 24px #2933420c;
  transition:
    transform var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    left var(--roc-duration, 560ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    background 0.25s;
}
.roc-folder-toggle > span:first-child {
  display: block;
  font-size: 13px;
  margin-bottom: 25px;
}
.roc-folder-toggle > span:last-child {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--roc-ink);
}
.roc-folder-toggle b {
  font-size: 18px;
  font-weight: 400;
}
.roc-folder[data-material="glass"] .roc-folder-toggle {
  background: color-mix(in srgb, var(--folder-color, #a8c6ee) 67%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.roc-folder.is-open .roc-folder-toggle {
  transform: translateX(-50%) perspective(650px) rotateX(-24deg);
}
.roc-folder[data-direction="right"] .roc-folder-back,
.roc-folder[data-direction="right"] .roc-folder-toggle {
  left: 28%;
  width: 162px;
}
.roc-folder[data-direction="right"] .roc-folder-toggle {
  transform-origin: 0% 50%;
}
.roc-folder[data-direction="right"].is-open .roc-folder-toggle {
  transform: translateX(-50%) perspective(650px) rotateY(-26deg);
}
@container (max-width:350px) {
  .roc-folder-card {
    width: 94px;
    height: 143px;
  }
  .roc-folder-card strong {
    font-size: 17px;
  }
  .roc-folder-toggle {
    width: 200px;
  }
  .roc-folder-back {
    width: 190px;
  }
  .roc-folder[data-direction="right"] .roc-folder-toggle,
  .roc-folder[data-direction="right"] .roc-folder-back {
    width: 132px;
  }
  .roc-folder[data-direction="right"] .roc-folder-toggle {
    padding: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-folder * {
    transition: none !important;
  }
}

.roc-folder-card { overflow: hidden; white-space: normal; }
.roc-folder-card strong { font-size: 16px; margin-top: 8px; }
.roc-folder-card .roc-card-content { margin-top: 8px; height: 74px; overflow: hidden; border-radius: 4px; }
.roc-folder-toggle { color: white; }
.roc-folder-toggle > span:last-child { color: rgb(255 255 255 / .8); }

/* The retained world has one spring transform writer, shared with BoardFolder. */
.roc-folder { overflow: hidden; }
.roc-folder-world { position: absolute; inset: 0; transform-origin: 0 0; }
.roc-folder .roc-folder-back { left: 0; top: 4px; width: 228px; height: 172px; transform: none; transition: none; }
.roc-folder .roc-folder-card { left: 0; top: 0; width: 118px; height: 152px; transition: box-shadow .2s; }
.roc-folder .roc-folder-toggle { left: 0; top: 24px; width: 228px; height: 152px; transform: none; transition: background .25s; }
.roc-folder .roc-folder-toggle { transform-origin: center bottom; }
.roc-folder[data-direction="right"] .roc-folder-toggle { transform-origin: left center; }

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-image-viewport:focus-visible,
.roc-page-book:focus-visible,
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-image-viewport:focus-visible,
  .roc-page-book:focus-visible,
  :where(
      .roc-expand,
      .roc-folder,
      .roc-sources,
      .roc-lanes,
      .roc-tabs,
      .roc-card-preview,
      .roc-image-viewport,
      .roc-voice,
      .roc-selection-toolbar,
      .roc-page-book,
      .roc-source-tray
    )
    button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

import { createPositionMotion, type MotionOptions } from "./franklin-react-motion-position";
import { containerSpring } from "./franklin-react-motion-spring";

/** Shared cover handoff and spring owner for standalone and canvas folders. */
export function createFolderLidMotion(node: HTMLElement, initial = 0, side = false) {
  const motion = createPositionMotion(node, { x: initial, y: 0 }, pose => {
    node.style.transform = `perspective(2000px) ${side ? `rotateY(${-pose.x}deg)` : `rotateX(${pose.x}deg)`}`;
  });
  let target = initial, timer: ReturnType<typeof setTimeout> | undefined;
  return {
    to(angle: number, reduced: boolean) {
      if (target === angle) return;
      target = angle; clearTimeout(timer);
      const run = () => motion.to({ x: angle, y: 0 }, reduced, {
        spring: angle === 24 ? { stiffness: 100, damping: 10, mass: .32 } : containerSpring(angle ? "lidOpen" : "lidClose"),
        preserveVelocity: false,
      });
      if (!angle && !reduced && motion.peek().x !== 0) timer = setTimeout(run, 100); else run();
    },
    finish() { clearTimeout(timer); motion.to({ x: target, y: 0 }, true); },
    dispose() { clearTimeout(timer); motion.dispose(); },
  };
}
export function folderItemMotion(open: boolean): MotionOptions {
  return { spring: containerSpring(open ? "unfold" : "refold"), preserveVelocity: false };
}

// Extracted from Franklin Board React worktree efca662 (MIT).
import { DEFAULT_SPRING, sampleSpring, type SpringOptions } from "./franklin-react-motion-spring";
import { poseOf, type Pose } from "./franklin-react-core-containers";
import type { Point } from "./franklin-react-core-types";
export interface MotionOptions { spring?: SpringOptions; preserveVelocity?: boolean; progressVelocity?: number; onFinish?: () => void }
export interface GeometryPose extends Pose { width: number; height: number }
const keys = ["x", "y", "scale", "rotation", "width", "height"] as const;
/** One transform writer per retained shell. Optional painter also drives camera/lid. */
export function createPositionMotion(node: HTMLElement, initial: Point & Partial<GeometryPose>, painter?: (pose: GeometryPose) => void) {
  let position: GeometryPose = { ...poseOf(initial), width: 0, height: 0, ...initial }, velocity: GeometryPose = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
